package com.mailservice.core

import scala.collection.mutable
import scala.concurrent.{Future, ExecutionContext}
import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.ConcurrentHashMap

// Kubernetes-deployed email sending service with rate limiting and quota management
// Deployed as StatefulSet with shared state via Redis (simulated here with in-memory store)

case class EmailMessage(id: String, to: String, from: String, subject: String, body: String)
case class QuotaState(remaining: Int, resetEpoch: Long, pendingCallbacks: List[String])

trait EmailTransport {
  def send(msg: EmailMessage): Future[Boolean]
}

class QuotaManager {
  // AtomicReference for lock-free quota management across async boundaries
  private val quotaRef = new AtomicReference[QuotaState](
    QuotaState(remaining = 100, resetEpoch = System.currentTimeMillis() + 3600000, pendingCallbacks = Nil)
  )

  private val deliveryLog = new ConcurrentHashMap[String, Boolean]()

  def tryAcquireQuota(messageId: String): Boolean = {
    var acquired = false
    var currentState = quotaRef.get()

    if (System.currentTimeMillis() > currentState.resetEpoch) {
      // Reset quota period - record pending message IDs for retry, then reset
      val pendingIds = currentState.pendingCallbacks
      val newState = QuotaState(
        remaining = 100,
        resetEpoch = System.currentTimeMillis() + 3600000,
        pendingCallbacks = Nil
      )
      if (quotaRef.compareAndSet(currentState, newState)) {
        // Pending IDs are returned to caller via getPendingRetries, no re-entrance
        acquired = decrementQuota(messageId)
      } else {
        // CAS failed, retry
        acquired = tryAcquireQuota(messageId)
      }
    } else if (currentState.remaining > 0) {
      acquired = decrementQuota(messageId)
    } else {
      // Quota exhausted - register message ID for later retry (data only, no callback)
      val newState = currentState.copy(
        pendingCallbacks = currentState.pendingCallbacks :+ messageId
      )
      if (!quotaRef.compareAndSet(currentState, newState)) {
        // CAS failed, retry
        acquired = tryAcquireQuota(messageId)
      }
    }
    acquired
  }

  private def decrementQuota(messageId: String): Boolean = {
    var success = false
    var done = false
    while (!done) {
      val current = quotaRef.get()
      if (current.remaining > 0) {
        val updated = current.copy(remaining = current.remaining - 1)
        if (quotaRef.compareAndSet(current, updated)) {
          deliveryLog.put(messageId, true)
          success = true
          done = true
        }
      } else {
        done = true
      }
    }
    success
  }

  def isDelivered(messageId: String): Boolean = {
    Option(deliveryLog.get(messageId)).getOrElse(false)
  }

  def getQuotaState: QuotaState = quotaRef.get()

  def getPendingRetries: List[String] = {
    val state = quotaRef.get()
    state.pendingCallbacks
  }
}

class EmailService(transport: EmailTransport, quotaManager: QuotaManager)(
  implicit ec: ExecutionContext
) {

  private val retryQueue = new ConcurrentHashMap[String, EmailMessage]()

  def sendEmail(msg: EmailMessage): Future[String] = {
    // Idempotency check
    if (quotaManager.isDelivered(msg.id)) {
      return Future.successful(s"already-delivered:${msg.id}")
    }

    val acquired = quotaManager.tryAcquireQuota(msg.id)

    if (acquired) {
      transport.send(msg).map { success =>
        if (success) s"sent:${msg.id}"
        else {
          retryQueue.put(msg.id, msg)
          s"queued-retry:${msg.id}"
        }
      }
    } else {
      retryQueue.put(msg.id, msg)
      Future.successful(s"quota-exceeded:${msg.id}")
    }
  }

  // Called by Kubernetes CronJob every minute
  def processRetryQueue(): Future[Int] = {
    val entries = new java.util.ArrayList[java.util.Map.Entry[String, EmailMessage]]()
    retryQueue.entrySet().forEach(e => entries.add(e))

    val futures = new mutable.ListBuffer[Future[Boolean]]()
    entries.forEach { entry =>
      val msg = entry.getValue
      // Simple quota acquisition - no callbacks, no re-entrance possible
      val acquired = quotaManager.tryAcquireQuota(msg.id)
      if (acquired) {
        retryQueue.remove(msg.id)
        futures += transport.send(msg).map(identity)
      }
    }
    Future.sequence(futures.toList).map(_.count(_ == true))
  }
}

// Health check endpoint for Kubernetes liveness probe
class HealthCheck(quotaManager: QuotaManager) {
  def isHealthy: Boolean = {
    val state = quotaManager.getQuotaState
    // Service is healthy if quota hasn't been negative (shouldn't happen)
    state.remaining >= 0
  }
}
